package wordwrap

import (
	"reflect"
	"testing"
)

func TestWordWrapBasic(t *testing.T) {
	got := WordWrap("the quick brown fox", 10)
	want := []string{"the quick", "brown fox"}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("got %v, want %v", got, want)
	}
}

func TestWordWrapSingleWord(t *testing.T) {
	got := WordWrap("hello", 5)
	want := []string{"hello"}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("got %v, want %v", got, want)
	}
}

func TestWordWrapEmpty(t *testing.T) {
	got := WordWrap("", 10)
	if len(got) != 0 {
		t.Errorf("expected empty, got %v", got)
	}
}

func TestWordWrapExactFit(t *testing.T) {
	got := WordWrap("abc def", 7)
	want := []string{"abc def"}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("got %v, want %v", got, want)
	}
}

func TestWordWrapLongWord(t *testing.T) {
	got := WordWrap("abcdefgh ij", 5)
	want := []string{"abcdefgh", "ij"}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("got %v, want %v", got, want)
	}
}
